ObjectStates.LuaScript:
function onSave()
        saved_data = self.script_state
        return saved_data
    end

    function onLoad(saved_data)
        if saved_data ~= "" then
            self.script_state = saved_data
            --print(script_state)
        else
            local bag_state = {
                tracked_objects = {}, -- The GUID's, and saved states of each object (Key = GUID, Value = Saved State).
                CONFIG = {
                    UPDATE_POS = true
                },
            }
            self.script_state = JSON.encode(bag_state)
        end

    end

